{- | Frozen owned native gems keep package-store discovery free of fixture file reads. The literals
copy the corpus gems @ecluse-fixture-root@ 1.0.0 and 2.0.0 under @test/fixtures/rubygems@, whose
manifest pins the same SHA-256 digests.
-}
module Ecluse.Test.Contract.PackageStore.RubyGems.Fixtures (
    NativeGem (..),
    packageText,
    packageName,
    primaryNative,
    siblingNative,
    gemFilename,
    nativeRow,
    storeRelease,
) where

import Data.ByteString qualified as BS
import Data.Map.Strict qualified as Map

import Ecluse.Core.Ecosystem (Ecosystem (RubyGems))
import Ecluse.Core.Package (PackageName, mkPackageName)
import Ecluse.Test.Contract.PackageStore
import Ecluse.Test.Package (hexSha256Of)

-- | One @ruby@-platform archive and the runtime dependency its specification declares.
data NativeGem = NativeGem
    { ngVersion :: Text
    , ngDependencies :: Text
    , ngArchive :: ByteString
    }

-- | Fixed package identity shared by the independent data and control planes.
packageText :: Text
packageText = "ecluse-fixture-root"

-- | Native gem names carry no namespace.
packageName :: PackageName
packageName = mkPackageName RubyGems Nothing packageText

-- | The leaf requirement differs from the sibling's, so each version has its own consumer fields.
primaryNative :: NativeGem
primaryNative = NativeGem "1.0.0" "ecluse-fixture-leaf:>= 1.0&< 2.0" primaryBytes

-- | The leaf requirement differs from the primary's, so each version has its own consumer fields.
siblingNative :: NativeGem
siblingNative = NativeGem "2.0.0" "ecluse-fixture-leaf:>= 1.0&< 3.0" siblingBytes

-- | The native filename of the package's @ruby@-platform archive for a version.
gemFilename :: Text -> Text
gemFilename version = packageText <> "-" <> version <> ".gem"

-- | The Compact Index row a store serves for a held archive, with the checksum of the bytes it holds.
nativeRow :: NativeGem -> Text
nativeRow gem = ngVersion gem <> " " <> ngDependencies gem <> "|checksum:" <> hexSha256Of (ngArchive gem) <> ",ruby:>= 3.2,rubygems:>= 3.4,created_at:2020-01-01T00:00:00Z"

-- | Consumer fields and the complete archive expected from an accepted native upload.
storeRelease :: NativeGem -> PackageStoreRelease
storeRelease gem =
    PackageStoreRelease
        (ngVersion gem)
        (Map.fromList [(filename <> " dependencies", ngDependencies gem), (filename <> " ruby", ">= 3.2"), (filename <> " rubygems", ">= 3.4")])
        (PackageStoreArtifact filename (ngArchive gem) (hexSha256Of (ngArchive gem)) :| [])
  where
    filename = gemFilename (ngVersion gem)

